        return 0

    n = len(arr)

    # Step 1: Calculate Maximum Sum Increasing Subsequence ending at each index i
    lis = [arr[0]] * n
    for i in range(1, n):
        current_max = -float('inf')
        for j in range(i):
            if arr[j] < arr[i]:
                # We want the max sum of an increasing subsequence ending at j + arr[i]
                candidate_sum = lis[j] + arr[i]
                if candidate_sum > current_max:
                    current_max = candidate_sum

        # If no smaller element found before, just take arr[i] itself (start new seq)
        if current_max == -float('inf'):
            lis[i] = arr[i]
        else:
            lis[i] = max(lis[i], current_max)

    # Step 2: Calculate Maximum Sum Decreasing Subsequence starting at each index i
    # We do this by reversing the array, finding LIS on reversed, then mapping back.

    rev_arr = arr[::-1]
    lds_rev = [rev_arr[0]] * n

    for i in range(1, len(rev_arr)):
        current_max = -float('inf')
        for j in range(i):
            if rev_arr[j] < rev_arr[i]: # In reversed array logic: looking backwards from peak means smaller elements come "after" (higher index) in original? 
                # Wait, let's rephrase strictly to avoid confusion.
                pass

    # Let's rewrite Step 2 more clearly without reversing indices mentally first

    lds = [arr[0]] * n
    for i in range(n - 1, -1, -1):
        current_max = arr[i] # At least the element itself
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                candidate_sum = lds[j] + arr[i]
                if candidate_sum > current_max:
                    current_max = candidate_sum
        lds[i] = max(arr[i], current_max)

